INSERT INTO `battlepay_display_info` VALUES ('1', '370664', '0', '0', 'X-53 Touring Rocket', '', 'Riding a giant cylinder filled with highly explosive goblin rocket fuel all by yourself is just crazy...so bring a friend.', '');
INSERT INTO `battlepay_display_info` VALUES ('2', '840662', '0', '0', 'Solar Spirehawk', '', 'Looking into the eyes of this mystical beast is like peering into the heart of the sun. Goggles are recommended when you\'re riding.', '');
INSERT INTO `battlepay_display_info` VALUES ('3', '134399', '0', '0', 'Black Qiraji Resonating Crystal', '', 'Although many varieties of Qiraji Battle Tank can still be found in the ruins of Ahn\'Qiraj today, the darkest of the species were only seen on the day the Scarab gong was rung.', '');
INSERT INTO `battlepay_display_info` VALUES ('4', '537515', '0', '0', 'Spectral Gryphon', '', 'When you said an old friend was coming back, this was not quite what I expected. -Bralla Cloudwing', '');
INSERT INTO `battlepay_display_info` VALUES ('5', '537531', '0', '0', 'Spectral Wind Rider', '', 'How do you not fall right through that thing? -Maztha', '');
INSERT INTO `battlepay_display_info` VALUES ('6', '587740', '0', '0', 'Feldrake', '', 'Fighting the Burning Legion millennia ago, this valiant drake fell to corruption after its body was infused with raw demonic magic.', '');
INSERT INTO `battlepay_display_info` VALUES ('7', '804461', '0', '0', 'Armored Bloodwing', '', 'This monstrous, flesh-eating bat is the undisputed ruler of the night skies.', '');
INSERT INTO `battlepay_display_info` VALUES ('8', '577318', '0', '0', 'Tyrael\'s Charger', '', 'A symbol of justice throughout all known realms.', '');
INSERT INTO `battlepay_display_info` VALUES ('9', '576138', '0', '0', 'Heart of the Aspects', '', 'You are Azeroth\'s true guardians and the future of this world is in your hands, for the dawning of the age of mortals has begun. - Alexstrasza', '');
INSERT INTO `battlepay_display_info` VALUES ('10', '132265', '0', '0', 'Blazing Hippogryph', '', 'Hippogryphs are highly intelligent, sentient beings; far more than mere \"mounts.', '');
INSERT INTO `battlepay_display_info` VALUES ('11', '132265', '0', '0', 'Corrupted Hippogryph', '', 'It is a sad fact that even the wise and majestic hippogryph may fall prey to corruption', '');
INSERT INTO `battlepay_display_info` VALUES ('12', '132188', '0', '0', 'Amani Dragonhawk', '', 'Dragonhawks liberated from troll enslavement are considered among the most loyal of all their kin.', '');
INSERT INTO `battlepay_display_info` VALUES ('13', '464162', '0', '0', 'Reins of the Spectral Wolf', '', 'Fears only fire.', '');
INSERT INTO `battlepay_display_info` VALUES ('14', '620831', '0', '0', 'Yu\'lei, Daughter of Jade', '', 'Warmth and wisdom emanate from this great creature, which glows like moonlight passing through the finest jade.', '');
INSERT INTO `battlepay_display_info` VALUES ('15', '1094600', '0', '0', 'Voidtalon of the Dark Star', '', 'Corrupted by the presence of the Dark Star in Draenor, the Voidtalons resisted being broken by the Shadowmoon Clan and were ultimately destroyed by Ner\'zhul. Only a single egg remains, lost in the void.', '');
INSERT INTO `battlepay_display_info` VALUES ('16', '986420', '0', '0', 'Grinning Reaver', '', 'The difference between a smile and a grin is the difference between a kiss and tasting.', '');
INSERT INTO `battlepay_display_info` VALUES ('17', '1247267', '0', '0', 'Reins of the Heavenly Azure Cloud Serpent', '', 'Warmth and serenity emanate from this great creature, which glows like the cloudless sky of a summer afternoon.', '');
INSERT INTO `battlepay_display_info` VALUES ('18', '796703', '0', '0', 'Ghastly Charger\'s Skull', '', 'Not all of Medivh\'s victims are gone for good.', '');
INSERT INTO `battlepay_display_info` VALUES ('19', '461144', '0', '0', 'Reins of the Drake of the North Wind', '', 'They sicken of the calm who know the storm.', '');
INSERT INTO `battlepay_display_info` VALUES ('20', '236232', '0', '0', 'Mottled Drake', '', 'I thought the thing was ill until it took to the air. It flies as true as any of my own. -Alexstrasza', '');
INSERT INTO `battlepay_display_info` VALUES ('22', '294032', '0', '0', 'Reins of the Rusted Proto-Drake', '', 'Not as shiny as the other one, but it\'s still a great find lads. Brann Bronzebeard', '');
INSERT INTO `battlepay_display_info` VALUES ('23', '298591', '0', '0', 'Reins of the Swift Spectral Tiger', '', 'Historians claim that these incorporeal beasts were created when Draenor exploded, unleashing energies that warped the world\'s flora and fauna.', '');
INSERT INTO `battlepay_display_info` VALUES ('24', '298586', '0', '0', 'Big Blizzard Bear', '', 'Whenever you ride this mount, you feel the urge to shout, \"Cry havoc and let slip the murlocs of war!\"', '');
INSERT INTO `battlepay_display_info` VALUES ('25', '236233', '0', '0', 'Reins of the Plagued Proto-Drake', '', 'Bred specifically to honor those heroes who showed significant courage and persistence facing the dangers in Northrend.', '');
INSERT INTO `battlepay_display_info` VALUES ('26', '236233', '0', '0', 'Reins of the Black Proto-Drake', '', 'Reins of the Black Proto-Drake', '');
INSERT INTO `battlepay_display_info` VALUES ('27', '133861', '0', '0', 'Mimiron\'s Head', '', 'A token of titan craftsmanship hoarded by the Old God, Yogg-Saron. Currently the single largest mechanical gnome head in Azeroth.', '');
INSERT INTO `battlepay_display_info` VALUES ('28', '254650', '0', '0', 'Reins of the Onyxian Drake', '', 'She has a lot in common with her mother, except for the being killed and reanimated. But she is young still. -Maloriak', '');
INSERT INTO `battlepay_display_info` VALUES ('29', '54069', '0', '0', 'Blazing Hippogryph', '', 'Hippogryphs are highly intelligent, sentient beings; far more than mere \"mounts.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('30', '369225', '0', '0', 'Celestial Steed', '', 'A beacon of hope; a guiding light in the darkness.', '');
INSERT INTO `battlepay_display_info` VALUES ('31', '132249', '0', '0', 'Vengeful Nether Drake', '', 'The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena.', '');
INSERT INTO `battlepay_display_info` VALUES ('32', '132249', '0', '0', 'Merciless Nether Drake', '', 'The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena.', '');
INSERT INTO `battlepay_display_info` VALUES ('33', '132249', '0', '0', 'Brutal Nether Drake', '', 'The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena.', '');
INSERT INTO `battlepay_display_info` VALUES ('34', '236235', '0', '0', 'Cataclysmic Gladiator\'s Twilight Drake', '', 'Heroes who proved their might in the gladiatorial arenas during the Cataclysm were awarded the most exceptional of the twilight drake broods.', '');
INSERT INTO `battlepay_display_info` VALUES ('35', '943739', '0', '0', 'Iron Skyreaver', '', 'Iron Horde beastmasters bred this rylak for war and then girded it for battle in black steel and smoldering flame.', '');
INSERT INTO `battlepay_display_info` VALUES ('36', '303868', '0', '0', 'Wrathful Gladiator\'s Frost Wyrm', '', 'Many believe that during their early lives, these wyrms were forced to fight their own kind for the amusement of others. Perhaps that is why they possess a particularly combative temperament.', '');
INSERT INTO `battlepay_display_info` VALUES ('37', '236235', '0', '0', 'Vicious Gladiator\'s Twilight Drake', '', 'Heroes who proved their might in the gladiatorial arenas during the Cataclysm were awarded the most exceptional of the twilight drake broods.', '');
INSERT INTO `battlepay_display_info` VALUES ('38', '399041', '0', '0', 'Heart of the Nightwing', '', 'When you can\'t run, you crawl, and when you can\'t crawl you find someone to carry you.', '');
INSERT INTO `battlepay_display_info` VALUES ('39', '303868', '0', '0', 'Deadly Gladiator\'s Frost Wyrm', '', 'These reanimated vessels of destruction do not fear death; they dispense it.', '');
INSERT INTO `battlepay_display_info` VALUES ('40', '303868', '0', '0', 'Relentless Gladiator\'s Frost Wyrm', '', 'In life, it could not be tamed, but necromancy and esoteric binding rituals have now combined to bend this indomitable creature to its rider\'s will.', '');
INSERT INTO `battlepay_display_info` VALUES ('41', '461141', '0', '0', 'Reins of the Phosphorescent Stone Drake', '', 'The Stonemother has shown little concern for the rebellious Aeonaxx, even allowing his spawn to be taken from her realm.', '');
INSERT INTO `battlepay_display_info` VALUES ('42', '303868', '0', '0', 'Furious Gladiator\'s Frost Wyrm', '', 'Some of Azeroth\'s mightiest dragons have been summoned across the veil between life and death to serve new masters with undying loyalty.', '');
INSERT INTO `battlepay_display_info` VALUES ('43', '132249', '0', '0', 'Swift Nether Drake', '', 'The most aggressive nether drakes were awarded those heroes who showed significant prowess and commitment in the gladiatorial arena.', '');
INSERT INTO `battlepay_display_info` VALUES ('44', '526356', '0', '0', 'Winged Guardian', '', 'Unearthed recently in an ancient tomb, this mighty winged lion may have once served one of the ancient Tol\'vir princes.', '');
INSERT INTO `battlepay_display_info` VALUES ('45', '135448', '0', '0', 'Big Love Rocket', '', 'Apothecary Hummel painted this masterpiece bright pink for an unrequited love.', '');
INSERT INTO `battlepay_display_info` VALUES ('46', '132199', '0', '0', 'Riding Turtle', '', 'Slow and steady might not always win you the race but it\'ll get you there... eventually.', '');
INSERT INTO `battlepay_display_info` VALUES ('47', '1044794', '0', '0', 'Tundra Icehoof', '', 'A translucent layer of down hair covers this breed\'s leathery hide, acting as the perfect insulation for cold environments', '');
INSERT INTO `battlepay_display_info` VALUES ('48', '930076', '0', '0', 'Warsong Direfang', '', 'Has a will of iron but is a sweetheart if you give it a clefthoof bone to chew on.', '');
INSERT INTO `battlepay_display_info` VALUES ('49', '841541', '0', '0', 'Enchanted Fey Dragon', '', 'This majestic creature is Brightwing\'s older brother. He affirms that she was, in fact, adopted.', '');
INSERT INTO `battlepay_display_info` VALUES ('50', '853211', '0', '0', 'Hearthsteed', '', 'Each step echoes with the rage of your three opponents.', '');
INSERT INTO `battlepay_display_info` VALUES ('51', '132199', '0', '0', 'Lucky Riding Turtle', '', 'Slow and steady might not always win you the race but it\'ll get you there... eventually.', '');
INSERT INTO `battlepay_display_info` VALUES ('52', '1044799', '0', '0', 'Armored Razorback', '', 'Never... ever... EVER... let it smell bacon on you.', '');
INSERT INTO `battlepay_display_info` VALUES ('53', '433440', '0', '0', 'Reins of Poseidus', '', '\"One has not truly lived until they have felt the tidal current rushing through their hair while atop a majestic seahorse,\" said no one. Ever.', '');
INSERT INTO `battlepay_display_info` VALUES ('54', '461145', '0', '0', 'Reins of the Drake of the South Wind', '', 'Gentle as a summer breeze, but that says little considering where it came from. -Itesh', '');
INSERT INTO `battlepay_display_info` VALUES ('55', '132834', '0', '0', 'Magic Rooster Egg', '', 'Magic in the hands of a genius can do wonderful, miraculous things. Magic in the hands of an idiot can make a giant rooster.', '');
INSERT INTO `battlepay_display_info` VALUES ('56', '773250', '0', '0', 'Swift Windsteed', '', 'One of Pandaria\'s most elusive creatures, said to bring good fortune to its rider.', '');
INSERT INTO `battlepay_display_info` VALUES ('57', '952015', '0', '0', 'Reins of the Dread Raven', '', 'Filled with the hatred of an ancient god, the dread raven are the Arakkoa\'s most trusted guardians.', '');
INSERT INTO `battlepay_display_info` VALUES ('58', '132198', '0', '0', 'Swift Shorestrider', '', 'A rarity amongst the tallstrider breeds of Kalimdor, but easily recognized by its pungent dead seaweed aroma.', '');
INSERT INTO `battlepay_display_info` VALUES ('59', '1044490', '0', '0', 'Mudback Riverbeast', '', 'Special webbing that grows on the soles of the mudback\'s feet gives them extra traction in mud and slick terrain.', '');
INSERT INTO `battlepay_display_info` VALUES ('60', '901301', '0', '0', 'Reins of the Thundering Onyx Cloud Serpent', '', 'This ebony cloud serpent is a lightning-wreathed vision of such rarity as to have driven many mortals to madness.', '');
INSERT INTO `battlepay_display_info` VALUES ('61', '1096090', '0', '0', 'Mystic Runesaber', '', 'Infused with arcane power, the Mystic Runesaber has long been hidden by chaotic nether energies. Recently they have emerged from the shadows in search of ley lines to sate their thirst for magic.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('62', '132372', '0', '0', 'Reins of the Raven Lord', '', 'The rest be forgotten to walk upon the ground, clipped wings and shame. -Word of the Raven', '');
INSERT INTO `battlepay_display_info` VALUES ('63', '986419', '0', '0', 'Warforged Nightmare', '', 'A nightmarish steed of hardened steel and vengeful spirits, this companion will follow you to the depths of the Firelands and back without complaint.', '');
INSERT INTO `battlepay_display_info` VALUES ('64', '929300', '0', '0', 'Emerald Hippogryph', '', 'These majestic animals come in various colorings, but the emerald variety can only be tamed by the magic of friendship.', '');
INSERT INTO `battlepay_display_info` VALUES ('65', '1085933', '0', '0', 'Cindermane Charger', '', 'Formed by Ragnaros himself as a gift for the daughter he never had.', '');
INSERT INTO `battlepay_display_info` VALUES ('66', '132262', '0', '0', 'X-51 Nether-Rocket X-TREME', '', 'What it lacks in safety features it more than makes up for in speed and style. Not for the faint of heart.', '');
INSERT INTO `battlepay_display_info` VALUES ('67', '236926', '0', '0', 'Core Hound Chain', '', 'Molten to the core!', '');
INSERT INTO `battlepay_display_info` VALUES ('68', '69228', '0', '0', 'Savage Raptor', '', 'One-time companion of Kanga the Primal, the fallen troll hero. The raptor\'s name is unknown, for Kanga only spoke to it in bear form.', '');
INSERT INTO `battlepay_display_info` VALUES ('69', '454772', '0', '0', 'Reins of the Grey Riding Camel', '', 'Fennimore Quigley is credited with milking the first camel and breaking the record for \"longest unintentional flight,\" all in the same afternoon.', '');
INSERT INTO `battlepay_display_info` VALUES ('70', '134060', '0', '0', 'Reins of the Dark War Talbuk', '', 'Despite their docile nature, talbuks have been known to gore seasoned warriors to death when threatened.', '');
INSERT INTO `battlepay_display_info` VALUES ('71', '1044798', '0', '0', 'Warlord\'s Deathwheel', '', 'Often referred to as the \"Goblin Lawn Mower\", this growling behemoth treats enemies like they are made of grass... ready to be mown down.', '');
INSERT INTO `battlepay_display_info` VALUES ('72', '1046124', '0', '0', 'Champion\'s Treadblade', '', 'Forged by human, gnome, and dwarf, this armored masterpiece is designed to slice a tauren into a tri-tip dinner with a flick of the handlebars.', '');
INSERT INTO `battlepay_display_info` VALUES ('73', '656173', '0', '0', 'Reins of the Thundering Jade Cloud Serpent', '', 'From their infancy, Thundering Cloud Serpents are drawn to storms. They have been known to chase lightning through the blackened, roiling clouds, and to bathe in the pouring rain.', '');
INSERT INTO `battlepay_display_info` VALUES ('74', '132261', '0', '0', 'Crusader\'s White Warhorse', '', 'Awarded to only the most skilled champions from the Trial of the Crusader, these steeds were chosen for Alliance members from Tirion Fordring\'s own personal stable.', '');
INSERT INTO `battlepay_display_info` VALUES ('75', '132224', '0', '0', 'Swift Horde Wolf', '', 'A few of the Argent Crusade\'s swiftest mounts were awarded to those members of the Horde who performed exceptionally during the tournament in Icecrown.', '');
INSERT INTO `battlepay_display_info` VALUES ('76', '132248', '0', '0', 'Frost Ram', '', '\"I\'ve not seen this breed in in ages, but when they\'re ram tough they stick around.\" -Veron Amberstill', '');
INSERT INTO `battlepay_display_info` VALUES ('77', '132117', '0', '0', 'Amani War Bear', '', 'Only the swiftest heroes venturing into the troll temple of Zul\'Aman were able to subdue these rare battle mounts.', '');
INSERT INTO `battlepay_display_info` VALUES ('78', '132266', '0', '0', 'Horn of the Arctic Wolf', '', 'Once thought to be nearly extinct, this wolf can still occasionally be seen in the company of a few Horde veterans.', '');
INSERT INTO `battlepay_display_info` VALUES ('79', '236245', '0', '0', 'Reins of the White Polar Bear', '', 'The frost vrykul believe that wearing a necklace of polar bear claws will grant them otherworldly strength.', '');
INSERT INTO `battlepay_display_info` VALUES ('80', '132117', '0', '0', 'Big Battle Bear', '', 'He\'s big, he\'s ready for battle, and he\'s a bear. What more could you want in a mount?', '');
INSERT INTO `battlepay_display_info` VALUES ('82', '132262', '0', '0', 'X-51 Nether-Rocket X-TREME', '', 'What it lacks in safety features it more than makes up for in speed and style. Not for the faint of heart.', '');
INSERT INTO `battlepay_display_info` VALUES ('83', '132226', '0', '0', 'Swift Zhevra', '', 'Zhevras are rarely used as mounts in Azeroth due to their stubborn nature and tendency to bite.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('84', '132261', '0', '0', 'Swift Alliance Steed', '', 'A few of the Argent Crusade\'s swiftest mounts were awarded to those members of the Alliance who performed exceptionally during the tournament in Icecrown.', '');
INSERT INTO `battlepay_display_info` VALUES ('85', '132251', '0', '0', 'Crusader\'s Black Warhorse', '', 'Awarded to only the most skilled champions from the Trial of the Crusader, these steeds were chosen for Horde members from Tirion Fordring\'s own personal stable.', '');
INSERT INTO `battlepay_display_info` VALUES ('86', '294468', '0', '0', 'Golden Gryphon', '', 'They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half. -Gryphon Master Talonaxe', '');
INSERT INTO `battlepay_display_info` VALUES ('87', '132263', '0', '0', 'X-51 Nether-Rocket', '', 'First designed as a booster for a much larger rocket, the X-51 was determined to give the perfect thrust capacity for a single rider payload.', '');
INSERT INTO `battlepay_display_info` VALUES ('88', '132261', '0', '0', 'Palomino Bridle', '', 'Human nobles have long favored this majestic breed for its beautiful golden coat and flowing white mane.', '');
INSERT INTO `battlepay_display_info` VALUES ('89', '132242', '0', '0', 'Swift Zulian Tiger', '', 'The last known Zulian tigers were kept by High Priest Thekal, deep within Zul\'Gurub. They are said to have been hunted into extinction.', '');
INSERT INTO `battlepay_display_info` VALUES ('90', '294467', '0', '0', 'Ebon Gryphon', '', '\"They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half.\"  -Gryphon Master Talonaxe', '');
INSERT INTO `battlepay_display_info` VALUES ('91', '454772', '0', '0', 'White Riding Camel', '', 'Fennimore Quigley is credited with milking the first camel and breaking the record for \"longest unintentional flight,\" all in the same afternoon.', '');
INSERT INTO `battlepay_display_info` VALUES ('92', '133936', '0', '0', 'Sea Turtle', '', 'Often caught by fishermen at a young age, these mounts are much more comfortable in the water than they are on land.', '');
INSERT INTO `battlepay_display_info` VALUES ('93', '644374', '0', '0', 'Imperial Quilen', '', 'Favorite pets of the ancient Mogu princes, Quilen make loyal and fearless companions and mounts.', '');
INSERT INTO `battlepay_display_info` VALUES ('94', '132198', '0', '0', 'Swift Forest Strider', '', 'This vibrant breed can only be found in the forests of Darkmoon Island.', '');
INSERT INTO `battlepay_display_info` VALUES ('95', '132244', '0', '0', 'Teal Kodo', '', '\"The kodo is the backbone of our people. Wherever the Horde goes - in trade, settlement, or war - there you will find the mighty kodo.\" - Harb Clawhoof', '');
INSERT INTO `battlepay_display_info` VALUES ('96', '132240', '0', '0', 'Flying Machine', '', 'The backbone of the Alliance air force is comprised predominantly of gnomish flying machines due to their maneuverability and speed.', '');
INSERT INTO `battlepay_display_info` VALUES ('98', '298589', '0', '0', 'Green Wind Rider', '', 'After being freed from vicious harpies by Cairne and Thrall, many of these creatures became valuable companions of the Horde.', '');
INSERT INTO `battlepay_display_info` VALUES ('99', '298588', '0', '0', 'Blue Wind Rider', '', 'After being freed from vicious harpies by Cairne and Thrall, many of these creatures became valuable companions of the Horde.', '');
INSERT INTO `battlepay_display_info` VALUES ('100', '298596', '0', '0', 'Tawny Wind Rider', '', 'After being freed from vicious harpies by Cairne and Thrall, many of these creatures became valuable companions of the Horde.', '');
INSERT INTO `battlepay_display_info` VALUES ('101', '294469', '0', '0', 'Snowy Gryphon', '', 'They love lions in Stormwind, and the gryphon is half lion. Of course they might not like which half. -Gryphon Master Talonaxe', '');
INSERT INTO `battlepay_display_info` VALUES ('102', '464141', '0', '0', 'Reins of the Dark Phoenix', '', 'Despite their name, Dark Phoenixes are known to have a warm and cheerful disposition.', '');
INSERT INTO `battlepay_display_info` VALUES ('103', '133785', '133789', '0', '1.000 Gold Coins', '', 'A Gold Boost of 1,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('104', '133785', '133789', '0', '5.000 Gold Coins', '', 'A Gold Boost of 5,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('105', '133785', '133789', '0', '10.000 Gold Coins', '', 'A Gold Boost of 10,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('106', '133785', '133787', '0', '30.000 Gold Coins', '', 'A Gold Boost of 30,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('107', '133785', '133784', '0', '80.000 Gold Coins', '', 'A Gold Boost of 80,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('108', '133785', '133785', '0', '150.000 Gold Coins', '', 'A Gold Boost of 150,000 Gold Coins!', '');
INSERT INTO `battlepay_display_info` VALUES ('109', '1033987', '1033987', '0', 'Level 100 Character Boost', '', 'There comes a time in every hero’s quest when they need a little boost to help get them over the hump and back into the action. With a Level 100 Character Boost, you can grant one character a one-time boost to level 100. Bring your hero up to speed and join the fight on the front lines.', '');
INSERT INTO `battlepay_display_info` VALUES ('110', '614740', '614740', '0', 'Level 90 Character Boost', '', 'There comes a time in every hero’s quest when they need a little boost to help get them over the hump and back into the action. With a Level 90 Character Boost, you can grant one character a one-time boost to level 90. Bring your hero up to speed and join the fight on the front lines.', '');
INSERT INTO `battlepay_display_info` VALUES ('111', '1126584', '614740', '0', 'Name Change', '', 'The name you originally chose for your hero doesn’t have to be his name for all eternity. Maybe you have become a little too famous (or notorious), or maybe you just thought of something better; either way, you can change your name and start anew today!', '');
INSERT INTO `battlepay_display_info` VALUES ('112', '1126583', '614740', '0', 'Faction Change', '', '‘Traitor’ is such a harsh word… sure, your allies may not be thrilled to see you leave, but what have they ever done for you, really? Maybe it’s time you saw what the other side has to offer. Maybe there are already friends waiting for you to join them. Maybe the epics really are purpler on the other side, as the saying goes. Changing factions also includes a free race change so you will fit right in with your new allies!', '');
INSERT INTO `battlepay_display_info` VALUES ('113', '1126585', '614740', '0', 'Race Change', '', 'It ain’t easy being green… or blue… or purplish-pink with pointy ears…. Sometimes a simple touch up of your character’s looks isn’t enough; sometimes you want to go all the way and change which race you belong to! With a race change, you can do just that.', '');
INSERT INTO `battlepay_display_info` VALUES ('114', '1126582', '614740', '0', 'Appearance Change', '', 'Things change, people change, hairstyles change, interest rates fluctuate… if you’re tired of always wearing a full plate helmet to hide your original character appearance choices, then appearance change is for you! Think of it like the kind of simple do-over people wished existed in real life. Appearance change lets you redo the look and even the gender of one of your characters.', '');
INSERT INTO `battlepay_display_info` VALUES ('115', '237245', '237245', '0', 'Rename Guild', '', 'We all made Typos... Mistakes were made....', '');
INSERT INTO `battlepay_display_info` VALUES ('116', '136240', '136240', '0', 'Alchemy - 800', '', 'Learn Alchemy 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('117', '134435', '441139', '0', 'Archeology - 800', '', 'Learn Archeology 800. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('118', '136241', '136241', '0', 'Blacksmithing - 800', '', 'Learn Blacksmithing 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('119', '133971', '571695', '0', 'Cooking - 800', '', 'Learn Cooking 800 with all recipes except Mists of Pandaria Quest Recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('120', '136244', '136244', '0', 'Enchanting - 800', '', 'Learn Enchanting 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('121', '136243', '136243', '0', 'Engineering - 800', '', 'Learn Engineering 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('122', '135966', '1014021', '0', 'First Aid - 800', '', 'Learn First Aid 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('123', '136245', '136245', '0', 'Fishing - 800', '', 'Learn Fishing 800. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('124', '136065', '136246', '0', 'Herbalist - 800', '', 'Learn Herbalist 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('125', '237171', '237171', '0', 'Inscription - 800', '', 'Learn Inscription 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('126', '134071', '134071', '0', 'Jewelcrafting - 800', '', 'Learn Jewelcrafting 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('127', '134366', '134366', '0', 'Skinning - 800', '', 'Learn Skinning 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('128', '136249', '136249', '0', 'Tailoring - 800', '', 'Learn Tailoring 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('129', '136248', '136248', '0', 'Mining - 800', '', 'Learn Mining 800. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('130', '133611', '136247', '0', 'Leatherworking - 800', '', 'Learn Leatherworking 800 with all recipes. Level 90 Character required.', '');
INSERT INTO `battlepay_display_info` VALUES ('131', '236689', '0', '0', 'Argent Squire', '', 'Many of Stormwind\'s youth joined the Argent Crusade as squires, hoping to one day serve the Holy Light in battle.', '');
INSERT INTO `battlepay_display_info` VALUES ('132', '134539', '0', '0', 'Netherwhelp\'s Collar', '', 'Offspring of the nether drakes of Outland, This young dragon is still growing into its role as Hunter, Protector, and Adorable Terror of the skies.', '');
INSERT INTO `battlepay_display_info` VALUES ('133', '132834', '0', '0', 'Blue Murloc Egg', '', 'Appearances of this beloved and ultra-reclusive murloc are sure to draw a crowd.', '');
INSERT INTO `battlepay_display_info` VALUES ('134', '132787', '0', '0', 'Diablo Stone', '', 'AND THE HEAVENS SHALL TREMBLE, AND MAN SHALL WEEP, AND THE END OF DAYS SHALL--wait, why are you so tall?', '');
INSERT INTO `battlepay_display_info` VALUES ('135', '132494', '0', '0', 'Panda Collar', '', 'This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature.', '');
INSERT INTO `battlepay_display_info` VALUES ('136', '1616898', '0', '0', 'Luminous Starseeker', '', 'Energetic apex hunters of Argus, the panthara hunt by sensing the energy within living things. A panthara approaching a powerful energy source will visibly change color and become more excited.', '');
INSERT INTO `battlepay_display_info` VALUES ('137', '133838', '0', '0', 'Dragon Kite', '', 'Much quieter than a real dragon.', '');
INSERT INTO `battlepay_display_info` VALUES ('138', '134154', '0', '0', 'Onyxian Whelpling', '', 'Spawn of Onyxia, this young dragon has decided that it doesn\'t want to follow in its grandfathers\' cataclysmic footsteps.', '');
INSERT INTO `battlepay_display_info` VALUES ('139', '132833', '0', '0', 'Hippogryph Hatchling', '', 'After a harpy incursion in Feralas, several hippogryph nesting grounds were attacked. Hundreds of hatchlings were orphaned, and they have been entrusted to the care of the druids on Sardor Isle.', '');
INSERT INTO `battlepay_display_info` VALUES ('140', '136039', '0', '0', 'Soul-Trader Beacon', '', 'Ethereal soul-traders will travel with those who can free the essences they need from unruly hosts.', '');
INSERT INTO `battlepay_display_info` VALUES ('141', '524050', '0', '0', 'Lil\' Tarecgosa', '', 'A legendary member of the blue dragonflight.', '');
INSERT INTO `battlepay_display_info` VALUES ('142', '574806', '0', '0', 'Soul of the Aspects', '', 'The Soul of the Aspects is said to be possessed of mercurial moods ranging from stoic and deliberate to unpredictable and erratic, to loving and deeply pensive.', '');
INSERT INTO `battlepay_display_info` VALUES ('143', '132834', '0', '0', 'Pink Murloc Egg', '', 'Gurky is a born performer, though she remains elusive, making public appearances only on the rarest of occasions.', '');
INSERT INTO `battlepay_display_info` VALUES ('144', '318523', '0', '0', 'Tuskarr Kite', '', 'Seeing these kites soaring above Northrend\'s shores is a clear sign that tuskarr are nearby.', '');
INSERT INTO `battlepay_display_info` VALUES ('145', '133278', '0', '0', 'Gold Medallion', '', 'These stunning creatures, awarded to heroes for victory in battle, represent Bravery and Strength.', '');
INSERT INTO `battlepay_display_info` VALUES ('146', '236191', '0', '0', 'Core Hound Pup', '', 'Found in the Firelands and the Molten Core, core hounds can trace their lineage back to the alpha male, Magmadar.', '');
INSERT INTO `battlepay_display_info` VALUES ('147', '327502', '0', '0', 'Unhatched Mr. Chilly', '', 'Mr. Chilly\'s appearance evokes a more civilized era, when duelists battled in tuxedos.', '');
INSERT INTO `battlepay_display_info` VALUES ('148', '132834', '0', '0', 'Heavy Murloc Egg', '', 'Only the rarest of murlocs is able to successfully cross dimensional barriers. Fewer still return with the kind of advanced armor and weaponry possessed by Grunty.', '');
INSERT INTO `battlepay_display_info` VALUES ('149', '134239', '0', '0', 'Warbot Ignition Key', '', 'A fighting robot fueled by delicious red or blue electrolytes.', '');
INSERT INTO `battlepay_display_info` VALUES ('150', '135128', '0', '0', 'Murkimus\' Little Spear', '', 'Murkimus is the most fearsome of all murloc arena warriors. And for a time, the only one.', '');
INSERT INTO `battlepay_display_info` VALUES ('151', '237441', '0', '0', 'Frosty\'s Collar', '', 'Accidentally created when the Lich King\'s deathly powers raised Rimefang from undeath.', '');
INSERT INTO `battlepay_display_info` VALUES ('152', '132599', '0', '0', 'Landro\'s Pet Box', '', 'NOTE: Not Guaranteed to Contain an Actual Pet', '');
INSERT INTO `battlepay_display_info` VALUES ('153', '298591', '0', '0', 'Spectral Tiger Cub', '', 'Affectionate and curious, these kittens seem to find the most peculiar hiding places.', '');
INSERT INTO `battlepay_display_info` VALUES ('154', '656513', '0', '0', 'Rocket Chicken', '', 'When the Burning Legion invaded Outland, Landro Longshot contributed this design to the war effort. Both the Alliance and Horde passed on production.', '');
INSERT INTO `battlepay_display_info` VALUES ('155', '133980', '0', '0', 'Banana Charm', '', 'Although loath to part with Bananas, Landro realized it would be safer if the pet was far from Booty Bay when his father, King Mukla, discovered he was missing.', '');
INSERT INTO `battlepay_display_info` VALUES ('156', '135128', '0', '0', 'Fetish Shaman\'s Spear', '', 'Fetish shaman are empowered by the spirits of their fallen ancestors. These malevolent spirits are bound to the shaman\'s tribal spear. Control this spear, and you control the shaman.', '');
INSERT INTO `battlepay_display_info` VALUES ('157', '132834', '0', '0', 'Lurky\'s Egg', '', 'Lurky\'s charming disposition and lively antics are guaranteed to soothe frustration and lighten even the darkest moods.', '');
INSERT INTO `battlepay_display_info` VALUES ('158', '132371', '0', '0', 'Blighted Spore', '', 'Loatheb\'s body is covered in small pods capable of spreading blighted fungal spores up to 1000 yards given proper wind conditions.', '');
INSERT INTO `battlepay_display_info` VALUES ('159', '666530', '0', '0', 'Cinder Kitten', '', 'A playful, purring pyromaniac. Don\'t pet these kittens without fireproof mittens!', '');
INSERT INTO `battlepay_display_info` VALUES ('160', '134430', '0', '0', 'Smoldering Murloc Egg', '', 'Deathwing\'s emergence transformed the whole of Azeroth; not even the ocean-dwelling murlocs were immune to his corrupt influence.', '');
INSERT INTO `battlepay_display_info` VALUES ('161', '656241', '0', '0', 'Cenarion Hatchling', '', 'Not yet the fearsome creatures they grow to in adulthood, the Cenarion hatchlings have an almost harmless appearance that has caught novice trainers of the Cenarion Circle off guard.', '');
INSERT INTO `battlepay_display_info` VALUES ('162', '254652', '0', '0', 'Lil\' Ragnaros', '', 'It\'s never too soon to summon this tiny aspect of the dread Firelord.', '');
INSERT INTO `battlepay_display_info` VALUES ('163', '467893', '0', '0', 'Moonkin Hatchling', '', 'Moonkin are blessed by Elune and spread nature\'s grace wherever they travel. The festive fowls are always in the mood for a dance.', '');
INSERT INTO `battlepay_display_info` VALUES ('164', '467894', '0', '0', 'Moonkin Hatchling', '', 'The distinct roar of the moonkin is one of the most terrifying sounds in nature.', '');
INSERT INTO `battlepay_display_info` VALUES ('165', '656595', '0', '0', 'Baneling', '', 'A rolling, explosive member of the Zerg swarm, the baneling deals terrible, terrible damage. Very dangerous in close quarters.', '');
INSERT INTO `battlepay_display_info` VALUES ('166', '134514', '0', '0', 'Landro\'s Lichling', '', 'How the goblin Landro Longshot initially came into possession of the lichling remains a mystery, but he was all too eager to wager it in a game of cards.', '');
INSERT INTO `battlepay_display_info` VALUES ('167', '519402', '0', '0', 'Guardian Cub', '', 'Still a little clumsy, this tiny winged lion is learning how to be the best mount it can be!', '');
INSERT INTO `battlepay_display_info` VALUES ('168', '525026', '0', '0', 'Hatespark the Tiny', '', 'His hate is not diminished by size.', '');
INSERT INTO `battlepay_display_info` VALUES ('169', '254104', '0', '0', 'Landro\'s Lil\' XT', '', 'Always \'ready to play,\' Landro\'s Lil\' XT is almost indistinguishable from the original. Prone to tantrums and narcolepsy.', '');
INSERT INTO `battlepay_display_info` VALUES ('170', '441880', '0', '0', 'Lil\' Deathwing', '', 'Similar to past companions rewarded through purchasing the Collector\'s Editions, this item will be mailed to all characters on the account.', '');
INSERT INTO `battlepay_display_info` VALUES ('171', '454042', '0', '0', 'Satyr Charm', '', 'A minion of Terestian Illhoof, this tricky imp was left in Karazhan when the portal to the Twisting Nether closed behind it.', '');
INSERT INTO `battlepay_display_info` VALUES ('172', '132871', '0', '0', 'Netherspace Portal-Stone', '', 'Upon leaving Netherspace, Malchezaar\'s Abyssals become strangely distorted by Karazhan\'s magical protections, rendering them tiny, and much less likely to spontaneously erupt in flames.', '');
INSERT INTO `battlepay_display_info` VALUES ('173', '294477', '0', '0', 'Magical Crawdad Box', '', 'Only magical wishes make magical crawdads. If you wish for a fish, fish for a wish.', '');
INSERT INTO `battlepay_display_info` VALUES ('174', '355498', '0', '0', 'Gusting Grimoire', '', 'A fel-tainted tome whose secrets are so terrible and bizarre that its pages have taken on an eerie semblance of life. Found on many a warlock\'s nightstand.', '');
INSERT INTO `battlepay_display_info` VALUES ('175', '463857', '0', '0', 'Jewel of Maddening Whispers', '', 'The bane of many an adventurer, to look into its eyes is to truly know madness.', '');
INSERT INTO `battlepay_display_info` VALUES ('176', '133570', '0', '0', 'Anubisath Idol', '', 'An anubisath idol from the Temple of Ahn\'qiraj, infused with ancient qiraji magic.', '');
INSERT INTO `battlepay_display_info` VALUES ('177', '136217', '0', '0', 'Zergling Leash', '', '\"A small, fierce member of the Zerg swarm, the zergling is not to be trifled with. Very dangerous in high numbers.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('178', '134399', '0', '0', 'Enchanted Onyx', '', 'The onyx panther is invisible at night, like a stalking shadow, and disappears with the dawn.', '');
INSERT INTO `battlepay_display_info` VALUES ('179', '237194', '0', '0', 'Enchanted Purple Jade', '', 'A rarely seen family of tigers, many believe (perhaps incorrectly) that some residual magic or other event is responsible for the unique color.', '');
INSERT INTO `battlepay_display_info` VALUES ('180', '132763', '0', '0', 'Turtle Box', '', 'Slow and steady wins the race.', '');
INSERT INTO `battlepay_display_info` VALUES ('181', '1044790', '0', '0', 'Argi', '', 'Often caught chewing on things they shouldn\'t be, goats were initially blamed for the crash of the Exodar.', '');
INSERT INTO `battlepay_display_info` VALUES ('182', '134183', '0', '0', 'Teldrassil Sproutling', '', 'It always wakes up dancing. What a happy little tree!', '');
INSERT INTO `battlepay_display_info` VALUES ('183', '133798', '0', '0', 'Sen\'jin Fetish', '', 'This is actually three pets in one. You won\'t know what you\'ll get until you summon it!', '');
INSERT INTO `battlepay_display_info` VALUES ('184', '134437', '0', '0', 'Toxic Wasteling', '', 'This, um, \'adorable\' little guy likes to play with critters. Just don\'t let them get too close.', '');
INSERT INTO `battlepay_display_info` VALUES ('185', '294471', '0', '0', 'Baby Blizzard Bear', '', 'This rare bear is bred for its small size and perpetually youthful appearance.', '');
INSERT INTO `battlepay_display_info` VALUES ('186', '132247', '0', '0', 'Mechanopeep', '', 'Used as a training mount for young gnomes, the Mechanopeep has none of the speed but all of the charm of its bigger brothers.', '');
INSERT INTO `battlepay_display_info` VALUES ('187', '1044791', '0', '0', 'Grommloc', '', 'No matter how much he screams, never give him demon blood.', '');
INSERT INTO `battlepay_display_info` VALUES ('188', '134324', '0', '0', 'Giant Sewer Rat', '', 'You wouldn\'t want to meet this rat in a dark alley. Or anywhere else, for that matter.', '');
INSERT INTO `battlepay_display_info` VALUES ('189', '656513', '0', '0', 'Mechanical Chicken', '', 'Not to worry; the combat mechanisms and homing logic have been disabled on this unit, I think. --Oglethorpe Obnoticus', '');
INSERT INTO `battlepay_display_info` VALUES ('190', '874857', '0', '0', 'Blossoming Ancient', '', 'This budding ancient is a unique variety in Azeroth, created from the ever-living branches of the Great Tree, and can bloom in any season.', '');
INSERT INTO `battlepay_display_info` VALUES ('191', '136155', '0', '0', 'Eye of the Legion', '', 'Always watching. Always judging.', '');
INSERT INTO `battlepay_display_info` VALUES ('192', '134186', '0', '0', 'Grell Moss', '', 'The grell are embodiments of the wild side of nature. Tame ones are very rare.', '');
INSERT INTO `battlepay_display_info` VALUES ('193', '135851', '0', '0', 'Ice Chip', '', 'While not nearly as destructive as its original master, the Ice Lord Ahune, the frostling has been known to lob chilly snowballs at unsuspecting adventurers.', '');
INSERT INTO `battlepay_display_info` VALUES ('194', '656128', '0', '0', 'Lucky Quilen Cub', '', '\"Offspring of the Imperial Quilen.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('195', '236177', '0', '0', 'Cobra Hatchling', '', 'The cobras of Azeroth are renowned for their fast-acting venom and swift strikes.', '');
INSERT INTO `battlepay_display_info` VALUES ('196', '615479', '0', '0', 'Murkalot\'s Flail', '', 'We\'re Crusaders from a fable. We dance whene\'er we\'re able. We do routines and chorus scenes, with footwork impeccable!', '');
INSERT INTO `battlepay_display_info` VALUES ('197', '236233', '0', '0', 'Proto-Drake Whelp', '', 'These voracious whelps grow at an incredible rate and can devour nearly twice their weight in raw meat per day.', '');
INSERT INTO `battlepay_display_info` VALUES ('198', '132835', '0', '0', 'A Jubling\'s Tiny Home', '', 'The Legendary Ale Frong was believed to be extinct until the strange brews at the Darkmoon Faire Brought them out of hiding.', '');
INSERT INTO `battlepay_display_info` VALUES ('199', '134931', '0', '0', 'Sand Scarab', '', 'Easily mistaken for a common beetle, the sting of a sand scarab will quickly clear up the misconception should you be unlucky enough to be stung by one.', '');
INSERT INTO `battlepay_display_info` VALUES ('200', '132186', '0', '0', 'Strand Crawler', '', 'The Strand Crawler has adapted to the Northern Cold by hibernating under the island beaches.', '');
INSERT INTO `battlepay_display_info` VALUES ('201', '132833', '0', '0', 'Sprite Darter Egg', '', '\"These adorable critters love snuggling with their owners after a long day of brutal, bloody battle.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('202', '132599', '0', '0', 'Cat Carrier (Black Tabby)', '', 'Old Alterac saying: \"A cat has nine lives, but needs only one.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('203', '387415', '0', '0', 'Mini Thor', '', 'Powerful artillery of the terran army. The Thor is always the first one in and the last one out!', '');
INSERT INTO `battlepay_display_info` VALUES ('204', '136036', '0', '0', 'Parrot Cage (Hyacinth Macaw)', '', 'Parrot Cage (Hyacinth Macaw)', '');
INSERT INTO `battlepay_display_info` VALUES ('205', '134154', '0', '0', 'Dark Whelpling', '', 'Hopes that someday it can grow up to destroy villages.', '');
INSERT INTO `battlepay_display_info` VALUES ('206', '134373', '0', '0', 'Phoenix Hatchling', '', 'A child of phoenix god Al\'ar, the hatchling takes flight immediately after birth.', '');
INSERT INTO `battlepay_display_info` VALUES ('207', '134155', '0', '0', 'Azure Whelpling', '', 'Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic.', '');
INSERT INTO `battlepay_display_info` VALUES ('208', '327735', '0', '0', 'Gryphon Hatchling', '', 'A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol.', '');
INSERT INTO `battlepay_display_info` VALUES ('209', '328269', '0', '0', 'Pandaren Monk', '', 'The pandaren monk is a fearless traveling companion, constantly training in his art... unless you offer him a drink. He considers it rude to refuse.', '');
INSERT INTO `battlepay_display_info` VALUES ('210', '134514', '0', '0', 'Lil\' Phylactery', '', 'n life, Kel\'Thuzad betrayed the Kirin Tor and created the Cult of the Damned. In death, he serves the Scourge as the Archlich Lord of Naxxramas.', '');
INSERT INTO `battlepay_display_info` VALUES ('211', '132193', '0', '0', 'Razzashi Hatchling', '', 'Razzashi raptors are among the cleverest predators in the jungle, making them favored by the Gurubashi trolls.', '');
INSERT INTO `battlepay_display_info` VALUES ('212', '132193', '0', '0', 'Deviate Hatchling', '', 'The demand for this purple-skinned breed has drastically reduced the raptor population near the Wailing Caverns.', '');
INSERT INTO `battlepay_display_info` VALUES ('213', '132253', '0', '0', 'Gundrak Hatchling', '', 'This crafty raptor was born in the icy wastes of Northrend. Its harsh upbringing gives it strength when many others would perish.', '');
INSERT INTO `battlepay_display_info` VALUES ('214', '136036', '0', '0', 'Parrot Cage (Green Wing Macaw)', '', 'Favored pet of the Defias pirates, this colorful bird is handy for remembering passwords, grocery lists, and cracker recipes.', '');
INSERT INTO `battlepay_display_info` VALUES ('215', '132598', '0', '0', 'Captured Firefly', '', 'Commonly used by sporelings as a light source as they navigate the waterways of Zangarmarsh, this luminescent insect helps them avoid the dangerous bogflare needlers.', '');
INSERT INTO `battlepay_display_info` VALUES ('216', '254104', '0', '0', 'Lil\' XT', '', 'Modeled after the huge titan prototype in Ulduar, this volatile little construct plays hard with its toys.', '');
INSERT INTO `battlepay_display_info` VALUES ('217', '237200', '0', '0', 'Murky\'s Little Soulstone', '', 'When you\'re confronting Murkablo or any of the Prime Murlocs, possession of a soulstone is strongly advised.', '');
INSERT INTO `battlepay_display_info` VALUES ('218', '133920', '0', '0', 'Purple Puffer', '', 'You might think this fish out of water would be a weak opponent... until you see the intensity that lies within its protective bubble.', '');
INSERT INTO `battlepay_display_info` VALUES ('219', '133858', '0', '0', 'Fortune Coin', '', 'Lucky squeals when he\'s angry or when he\'s eating. Either way, you don\'t want to bother him.', '');
INSERT INTO `battlepay_display_info` VALUES ('220', '328270', '0', '0', 'Wind Rider Cub', '', 'Thog No-Legs never paid heed to the old orc saying, \'Don\'t pull a wyvern\'s tail.\'', '');
INSERT INTO `battlepay_display_info` VALUES ('221', '135277', '0', '0', 'Tyrael\'s Hilt', '', '\'I am Justice itself!\'', '');
INSERT INTO `battlepay_display_info` VALUES ('222', '519402', '0', '0', 'Guardian Cub', '', 'Still a little clumsy, this tiny winged lion is learning how to be the best mount it can be!', '');
INSERT INTO `battlepay_display_info` VALUES ('223', '134157', '0', '0', 'Emerald Whelpling', '', 'Once bred and raised by the green dragon Itharius, this unique breed has settled in the jungles of Feralas.', '');
INSERT INTO `battlepay_display_info` VALUES ('224', '294472', '0', '0', 'Baby Shark', '', 'Baby shark, doo, doo, doo, doo, doo, doo. Full scripted in V2, partially scripted and abandoned by Blizzard durning Developement.', '');
INSERT INTO `battlepay_display_info` VALUES ('225', '134153', '0', '0', 'Tiny Crimson Whelpling', '', 'Hailing from the Wetlands, this young dragon is just learning how to hunt, breathe fire, and go on cute destructive rampages.', '');
INSERT INTO `battlepay_display_info` VALUES ('226', '132806', '0', '0', 'Chuck\'s Bucket', '', 'After studying the crocolisk species for several years, the famed angler Nat Pagle determined that baby crocolisks are mostly harmless.', '');
INSERT INTO `battlepay_display_info` VALUES ('227', '132193', '0', '0', 'Darting Hatchling', '', 'Rarely leaves nest until maturity. Enjoys conducting pranks on the nearby Razormaw nest.', '');
INSERT INTO `battlepay_display_info` VALUES ('228', '132253', '0', '0', 'Leaping Hatchling', '', 'This offspring of Takk the Leaper is incredibly agile and can maneuver through difficult environments with ease.', '');
INSERT INTO `battlepay_display_info` VALUES ('229', '1616893', '0', '0', 'Twilight', '', 'This energetic kitten changes colors depending on its mood', '');
INSERT INTO `battlepay_display_info` VALUES ('230', '132806', '0', '0', 'Snarly\'s Bucket', '', '\"Crocolisks are six-legged amphibian predators found in coastal waters. Archaeologists believe they may be descended from the diemetradons of Un\'Goro Crater.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('231', '237579', '0', '0', 'Mojo', '', 'Amani Witch Doctors have turned many victims into frogs. Some NEVER RECOVER.', '');
INSERT INTO `battlepay_display_info` VALUES ('232', '132253', '0', '0', 'Ravasaur Hatchling', '', 'Larger than other raptor infants, these hatchlings grow into towering reptilian beasts capable of massive devastation.', '');
INSERT INTO `battlepay_display_info` VALUES ('233', '236547', '0', '0', 'Feline Familiar', '', 'Ride with the moon (and this furry, whiskered witch) in the dead of night!', '');
INSERT INTO `battlepay_display_info` VALUES ('234', '433440', '0', '0', 'Sea Pony', '', 'Despite its diminutuve size, it is IMPOSSIBLE to miss a sea pony cutting through the water.', '');
INSERT INTO `battlepay_display_info` VALUES ('235', '132832', '0', '0', 'Smolderweb Egg', '', 'Although born in the warm heights of Blackrock Spire, the smolderweb hatchling can survive most environments.', '');
INSERT INTO `battlepay_display_info` VALUES ('236', '134567', '0', '0', 'Elementium Geode', '', 'Often confused by miners as a rare gem, the geode initially makes its presence known by emitting melodic reverberations.', '');
INSERT INTO `battlepay_display_info` VALUES ('237', '952507', '0', '0', 'Dread Hatchling', '', 'The dark wings will cloud and consume the minds of the weak, because they are just so adorable!', '');
INSERT INTO `battlepay_display_info` VALUES ('238', '370211', '0', '0', 'Treasure Goblin\'s Pack', '', 'Watch your coin purse.', '');
INSERT INTO `battlepay_display_info` VALUES ('239', '135777', '0', '0', 'Ominous Flame', '', 'The odd blue flames found within The Cavern Of Lost Spirits have led many unwary adventurers to their doom.', '');
INSERT INTO `battlepay_display_info` VALUES ('240', '132620', '0', '0', 'Alterac Brandy', '', 'A mastiff bred for rescue, the Alterac brewhound\'s bloodline is famous for having found and resuscitated many mountain travelers trapped beneath the snow... and then slobbering all over them.', '');
INSERT INTO `battlepay_display_info` VALUES ('241', '132514', '0', '0', 'Piglet\'s Collar', '', 'Many assume \'Wiggles\' refers to the motion of this pig\'s posterior. They discover the true meaning when they see their own entrails.', '');
INSERT INTO `battlepay_display_info` VALUES ('242', '132242', '0', '0', 'Nightsaber Cub', '', 'Elune made nightsabers silver and black so they could meld into the shadows on a moonlit night.', '');
INSERT INTO `battlepay_display_info` VALUES ('243', '132193', '0', '0', 'Razormaw Hatchling', '', 'Razormaw eggs are protected fiercely by their mothers. Their cuteness belies their inherited ferocity.', '');
INSERT INTO `battlepay_display_info` VALUES ('244', '134579', '0', '0', 'Lump of Coal', '', 'A stowaway from Greatfather Winter\'s workshop, this tiny elemental found himself trapped in a present that was stolen by the Abominable Greench.', '');
INSERT INTO `battlepay_display_info` VALUES ('245', '646148', '0', '0', 'Terrible Turnip', '', '\"And you thought turnips at the dinner table were bad.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('246', '132806', '0', '0', 'Toothy\'s Bucket', '', 'The crocolisk\'s hide and meat are prized by hunters, but the beast is ferocious and seldom taken by surprise.', '');
INSERT INTO `battlepay_display_info` VALUES ('247', '132198', '0', '0', 'Mulgore Hatchling', '', 'A tallstrider\'s speed on open ground is unrivaled, so predators rely on stealth and pack tactics when hunting them.', '');
INSERT INTO `battlepay_display_info` VALUES ('248', '136071', '0', '0', 'Elwynn Lamb', '', 'Unlike the polymorphed variety, trueborn sheep can be quite scary.', '');
INSERT INTO `battlepay_display_info` VALUES ('249', '132195', '0', '0', 'Durotar Scorpion', '', 'The volatile Durotar scorpion is a fierce desert predator. It\'s known for only occasionally stinging its owner.', '');
INSERT INTO `battlepay_display_info` VALUES ('250', '252780', '0', '0', 'Curious Oracle Hatchling', '', 'The bouncy gurloc is a distant cousin of the murloc.', '');
INSERT INTO `battlepay_display_info` VALUES ('251', '236243', '0', '0', 'Dun Morogh Cub', '', 'The bears of Dun Morogh are prized for their hardiness, loyalty, and combat prowess. Their time among the dwarves does little to curb their ferocity.', '');
INSERT INTO `battlepay_display_info` VALUES ('252', '134813', '0', '0', 'Captured Flame', '', '\"This little piece of summer smells of warm evenings and lightning storms. If you look closely, you might be able to make out a face.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('253', '132182', '0', '0', 'Tirisfal Batling', '', 'Can sense an opponent\'s heartbeat through echolocation.', '');
INSERT INTO `battlepay_display_info` VALUES ('254', '133000', '0', '0', 'Clockwork Rocket Bot', '', 'This mechanical warrior is a favorite gift during Winter Veil. Batteries not included, but rockets definitely are!', '');
INSERT INTO `battlepay_display_info` VALUES ('255', '132382', '0', '0', 'Truesilver Shafted Arrow', '', 'The power of love can be a dangerous thing, especially when wielded by an airborne, ill-tempered goblin.', '');
INSERT INTO `battlepay_display_info` VALUES ('256', '133000', '0', '0', 'Blue Clockwork Rocket Bot', '', 'Jepetto\'s top-selling toy this season, the bot\'s new blue chassis has children across Azeroth scrambling for this feisty battle bot.', '');
INSERT INTO `battlepay_display_info` VALUES ('257', '236698', '0', '0', 'Curious Wolvar Pup', '', 'Despite their smaller stature, the wolvar are some of the most aggressive creatures in Northrend. This often makes their curious nature intimidating.', '');
INSERT INTO `battlepay_display_info` VALUES ('258', '655994', '0', '0', 'Enchanted Broom', '', 'Created by a blood elf apprentice, this broom would be extremely useful if anyone could figure out how to make it stop.', '');
INSERT INTO `battlepay_display_info` VALUES ('259', '132833', '0', '0', 'Chicken Egg', '', 'Don\'t call this bird chicken unless you want egg on your face.', '');
INSERT INTO `battlepay_display_info` VALUES ('260', '656600', '0', '0', 'Pint-Sized Pink Pachyderm', '', 'A shy creature, the Pink Elekk will only make its presence known to those that have befriended it, or to anyone too intoxicated to harm it.', '');
INSERT INTO `battlepay_display_info` VALUES ('261', '132192', '0', '0', 'White Tickbird Hatchling', '', '\"The rare albino tickbird is revered amongst the Oracles. It is seen as a sign of heavy rainstorms, good grub harvests, and hibernating wolvar.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('262', '132253', '0', '0', 'Obsidian Hatchling', '', 'This hatchling is coveted for its unique coloration. Despite Breanni\'s loving care, the raptor\'s feral nature cannot be restrained.', '');
INSERT INTO `battlepay_display_info` VALUES ('263', '132762', '0', '0', 'Wood Frog Box', '', 'Vendors at the Darkmoon Faire offer strange and exotic wonders. They also sell wood frogs.', '');
INSERT INTO `battlepay_display_info` VALUES ('264', '132762', '0', '0', 'Tree Frog Box', '', 'Tree Frog Box is sold by Flik at the Darkmoon Faire, which appears in Mulgore, Elwynn Forest, and Terokkar Forest for 1g.', '');
INSERT INTO `battlepay_display_info` VALUES ('265', '132806', '0', '0', 'Muckbreath\'s Bucket', '', 'Muckbreath is just like other crocolisks, except he has an excellent sense of humor.', '');
INSERT INTO `battlepay_display_info` VALUES ('266', '132599', '0', '0', 'Cat Carrier (Calico Cat)', '', 'Many have mocked this cat before battle. Their last words are usually, \"Here, kitty, kitty.\"', '');
INSERT INTO `battlepay_display_info` VALUES ('267', '132599', '0', '0', 'Cat Carrier (Siamese)', '', 'Known for its blue eyes. Also considered a delicacy by giant murlocs.', '');
INSERT INTO `battlepay_display_info` VALUES ('268', '132192', '0', '0', 'Tickbird Hatchling', '', 'Unlike most of Geen the gorloc\'s \'mysterious eggs,\' this one actually contained a living thing.', '');
INSERT INTO `battlepay_display_info` VALUES ('269', '237272', '0', '0', 'Macabre Marionette', '', 'These possessed puppets are given a semblance of life by whimsical spirits of the departed.', '');
INSERT INTO `battlepay_display_info` VALUES ('270', '446127', '0', '0', 'Hyjal Bear Cub', '', 'The cubs of Hyjal suffered much during the Cataclysm. On the bright side, the devastation also led to their newfound love of heights and daredevil stunts.', '');
INSERT INTO `battlepay_display_info` VALUES ('271', '135263', '0', '0', 'Crimson Lasher', '', 'Native to the ashen soils of the Firelands, the lasher was transplanted to Azeroth with the help of the Guardians of Hyjal.', '');
INSERT INTO `battlepay_display_info` VALUES ('272', '132849', '0', '0', 'Shimmering Wyrmling', '', 'This extremely rare species of mana wyrm is prized for its unique coloration and even temperament.', '');
INSERT INTO `battlepay_display_info` VALUES ('273', '132849', '0', '0', 'Shimmering Wyrmling', '', 'This extremely rare species of mana wyrm is prized for its unique coloration and even temperament.', '');
INSERT INTO `battlepay_display_info` VALUES ('274', '132107', '0', '0', 'Disgusting Oozeling', '', 'Warning: Wear gloves and goggles while handling disgusting oozeling. DO NOT WASH. Will stain most armor.', '');
INSERT INTO `battlepay_display_info` VALUES ('275', '132182', '0', '0', 'Vampiric Batling', '', 'Vampire bats have been trained as scouts and mounts by the Forsaken of the Undercity and the Amani trolls of Zul\'Aman.', '');
INSERT INTO `battlepay_display_info` VALUES ('276', '133718', '0', '0', 'Perky Pug', '', 'Although small, pugs are very dangerous when provoked.', '');
INSERT INTO `battlepay_display_info` VALUES ('277', '132191', '0', '0', 'Nether Ray Fry', '', 'Native to the Terokkar Forest, Nether Rays spawn during the rainy season. Out of the hundreds of offspring resulting from one hatching, very few survive to adulthood.', '');
INSERT INTO `battlepay_display_info` VALUES ('278', '136006', '0', '0', 'Mana Wyrmling', '', 'The ethereal Rashaad began breeding these enigmatic creatures after learning of their ability to feed on arcane energies.', '');
INSERT INTO `battlepay_display_info` VALUES ('279', '132599', '0', '0', 'Rat Cage', '', 'A clever tactician, Whiskers will feign death to fool predators and bill collectors.', '');
INSERT INTO `battlepay_display_info` VALUES ('280', '133941', '0', '0', 'Ammen Vale Lashling', '', 'The long-term effects of the contamination caused by the Exodar are still under observation.', '');
INSERT INTO `battlepay_display_info` VALUES ('329', '514340', '514340', '0', 'Blazing Wings', '', 'Blazing Wings gives the character wings similar to those seen in the Alysrazor boss encounter in the Firelands raid instance.', '');
INSERT INTO `battlepay_display_info` VALUES ('330', '236415', '236415', '0', 'Demon Hunter\'s Aspect', '', 'Resemble a Demon Hunter', '');
INSERT INTO `battlepay_display_info` VALUES ('331', '134169', '134169', '0', 'Murloc Costume', '', 'It\'s a Murloc Costume', '');
INSERT INTO `battlepay_display_info` VALUES ('332', '840662', '840662', '0', 'Jewel of the Firelord', '', 'Salvaged from the remains of the fallen minions of Ragnaros the Firelord, this helm sets you apart as a glowing beacon on an otherwise crowded battlefield. Where’s the rally point? How about by that guy with the RAW ELEMENTAL FIRE emanating from his forehead?', '');
INSERT INTO `battlepay_display_info` VALUES ('333', '134230', '134230', '0', 'Carved Ogre Idol', '', 'Become a hulking red ogre for 10 min!', '');
INSERT INTO `battlepay_display_info` VALUES ('334', '134519', '134519', '0', 'Goblin Weather Machine - Prototype 01-B', '', 'It\'s a rainy day.', '');
INSERT INTO `battlepay_display_info` VALUES ('335', '841875', '841875', '0', 'Hood of Hungering Darkness', '', 'Forged from Fel Iron and shrouded in flames, the Hood of Hungering Darkness is a remnant of a rare dark magic only practiced by the warlocks of the Shadow Council. The lingering curse that keeps this headpiece burning is thought to be harmless, but feign demonic possession once you adorn it and see who dares to believe otherwise.', '');
INSERT INTO `battlepay_display_info` VALUES ('336', '841140', '841140', '0', 'Crown of Eternal Winter', '', 'Recovered from the frozen battlefields of Northrend, the Crown of Eternal Winter enshrouds your character in an icy visage of death. Now, you can adopt the look of an elite member of the Scourge, but without the inconvenience of undying bondage in the service of the Lich King.', '');
INSERT INTO `battlepay_display_info` VALUES ('337', '237284', '237284', '0', 'Decahedral Dwarven Dice', '', 'Rolls a pair of dice.', '');
INSERT INTO `battlepay_display_info` VALUES ('338', '134112', '134112', '0', 'Fool\'s Gold', '', 'Players may use the node to summon temporary Greedy Kobold non-combat pets.', '');
INSERT INTO `battlepay_display_info` VALUES ('339', '249182', '249182', '0', 'Shado-Pan Geyser Gun', '', 'Unload a torrent of water on allies and enemies with the Geyser Gun. ', '');
INSERT INTO `battlepay_display_info` VALUES ('340', '134372', '134372', '0', 'Papa Hummel\'s Old-Fashioned Pet Biscuit', '', 'Doubles a targeted Companion Pet\'s size for as long as it remains at its master\'s side.', '');
INSERT INTO `battlepay_display_info` VALUES ('341', '133639', '133639', '0', 'Sack of Starfish', '', 'Create 5 Throwing Starfish.', '');
INSERT INTO `battlepay_display_info` VALUES ('342', '454069', '454069', '0', 'Spurious Sarcophagus', '', 'Climb into a sarcophagus for 5 min.', '');
INSERT INTO `battlepay_display_info` VALUES ('343', '134335', '134335', '0', 'Mini Mana Bomb', '', 'Toss your Mini Mana Bomb.', '');
INSERT INTO `battlepay_display_info` VALUES ('344', '132484', '132484', '0', 'The Flag of Ownership', '', 'Place a flag on an enemy player\'s corpse in front of you.', '');
INSERT INTO `battlepay_display_info` VALUES ('345', '134472', '134472', '0', 'Tabard of Frost', '', 'The Tabard of Frost is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('346', '134334', '134334', '0', 'Orb of Deception', '', 'Transforms caster to look like a member of the opposing faction for 5 min. (', '');
INSERT INTO `battlepay_display_info` VALUES ('347', '134334', '134334', '0', 'Orb of the Sin\'dorei', '', 'Disguises the user as a blood elf.', '');
INSERT INTO `battlepay_display_info` VALUES ('348', '132930', '132930', '0', 'Fishing Chair', '', 'Set up a comfy fishing chair.', '');
INSERT INTO `battlepay_display_info` VALUES ('349', '133836', '133836', '0', 'D.I.S.C.O.', '', 'Start the dance party!', '');
INSERT INTO `battlepay_display_info` VALUES ('350', '236222', '236222', '0', 'Ethereal Portal', '', 'Returns you to your <home location>.', '');
INSERT INTO `battlepay_display_info` VALUES ('351', '135028', '135028', '0', 'Epic Purple Shirt', '', 'The first epic-quality shirt-slot item.', '');
INSERT INTO `battlepay_display_info` VALUES ('352', '306868', '306868', '0', 'Ogre Pinata', '', 'Places a candy-filled Ogre Pinata.', '');
INSERT INTO `battlepay_display_info` VALUES ('353', '132594', '132594', '0', 'Picnic Basket', '', 'Set up a relaxing little picnic.', '');
INSERT INTO `battlepay_display_info` VALUES ('354', '133884', '133884', '0', 'Eye of Arachnida', '', 'Summons an Eye of Kilrogg and binds your vision to it. The eye moves quickly but is very fragile.', '');
INSERT INTO `battlepay_display_info` VALUES ('355', '135463', '135463', '0', 'Dartol\'s Rod of Transformation', '', 'Transforms you into a Furbolg for 3 min.', '');
INSERT INTO `battlepay_display_info` VALUES ('356', '134911', '134911', '0', 'Time-Lost Figurine', '', 'Transforms caster to have the appearance of a Skettis arakkoa.', '');
INSERT INTO `battlepay_display_info` VALUES ('357', '255139', '255139', '0', 'Gnomeregan Pride', '', 'Transform into Gnomeregan Infantry.', '');
INSERT INTO `battlepay_display_info` VALUES ('358', '255145', '255145', '0', 'Darkspear Pride', '', 'Transform into a Darkspear Warrior.', '');
INSERT INTO `battlepay_display_info` VALUES ('359', '134335', '134335', '0', 'Super Simian Sphere', '', 'Go wild in a bubble for 5 min.', '');
INSERT INTO `battlepay_display_info` VALUES ('360', '135026', '135026', '0', 'Tabard of Fury', '', 'The Tabard of Fury is one of eight rare tabards', '');
INSERT INTO `battlepay_display_info` VALUES ('361', '134473', '134473', '0', 'Tabard of Flame', '', 'The Tabard of Flame is one of eight rare tabards', '');
INSERT INTO `battlepay_display_info` VALUES ('362', '135026', '135026', '0', 'Tabard of Brilliance', '', 'The Tabard of Brilliance is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('363', '135026', '135026', '0', 'Tabard of the Void', '', 'The Tabard of Void is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('364', '135026', '135026', '0', 'Tabard of the Arcane', '', 'The Tabard of Arcane is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('365', '135026', '135026', '0', 'Tabard of Nature', '', 'The Tabard of Nature is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('366', '135026', '135026', '0', 'Tabard of the Defender', '', 'The Tabard of the Defender is one of eight rare tabards.', '');
INSERT INTO `battlepay_display_info` VALUES ('367', '135794', '135794', '0', 'Path of Illidan', '', 'Leaves flickering fel fire in your wake for 5 min.', '');
INSERT INTO `battlepay_display_info` VALUES ('368', '134152', '134152', '0', 'Wind-Up Train Wrecker', '', 'Sets down a wind-up train wrecker', '');
INSERT INTO `battlepay_display_info` VALUES ('369', '134284', '134284', '0', 'Perpetual Purple Firework', '', 'Shoots a firework into the air that bursts into a thousand purple stars.', '');
INSERT INTO `battlepay_display_info` VALUES ('370', '132261', '132261', '0', 'War Party Hitching Post', '', 'Party or raid members with at least Apprentice Riding may use the post to summon a Hitch Horse mount. ', '');
INSERT INTO `battlepay_display_info` VALUES ('371', '134230', '134230', '0', 'Magical Ogre Idol', '', 'Become a red ogre mage for 5 min. ', '');
INSERT INTO `battlepay_display_info` VALUES ('372', '425951', '425951', '0', 'Grim Campfire', '', 'Builds a grim campfire that isn\'t going to increase anyone\'s spirit. In fact, it may creep them out a bit. It does allow cooking, though.', '');
INSERT INTO `battlepay_display_info` VALUES ('373', '442743', '442743', '0', 'Warning Sign', '', 'Place a Warning Sign that lasts for 60 sec. A message can be carved into the sign, causing it to last for 60 min and making it visible to other players', '');
INSERT INTO `battlepay_display_info` VALUES ('374', '132719', '132719', '0', 'Ruthers\' Harness', '', 'Summon Ruthers, the bad yak.', '');
INSERT INTO `battlepay_display_info` VALUES ('375', '133980', '133980', '0', 'The Golden Banana', '', 'Throw The Golden Banana. ', '');
INSERT INTO `battlepay_display_info` VALUES ('376', '801002', '801002', '0', 'Whole-Body Shrinka\'', '', 'Head-shrinking is for amateurs. Shrink your whole body!', '');
